Here is the commit message:
net: lan966x: improve error handle in
 lan966x_fdma_rx_get_frame()

Don't just print a warning.  Clean up and return an error as well.

Fixes: c8349639324a ("net: lan966x: Add FDMA functionality")
Signed-off-by: Dan Carpenter <dan.carpenter@oracle.com>
Reviewed-by: Horatiu Vultur <horatiu.vultur@microchip.com>
Link: https://lore.kernel.org/r/YwjgDm/SVd5c1tQU@kili
Signed-off-by: Jakub Kicinski <kuba@kernel.org>

Here is the root cause:
The bug arises from inadequate error handling in the `lan966x_fdma_rx_get_frame` function, where an invalid `src_port` value could lead to a warning being issued without proper cleanup of the allocated socket buffer (`skb`). This oversight could result in memory leaks if the function exits without freeing the `skb` when an error condition is encountered.

Here is the patch:

 static struct sk_buff *lan966x_fdma_rx_get_frame(struct lan966x_rx *rx)
 {
 	struct lan966x *lan966x = rx->lan966x;
 	u64 src_port, timestamp;
 	struct lan966x_db *db;
 	struct sk_buff *skb;
 	struct page *page;

 	/* Get the received frame and unmap it */
 	db = &rx->dcbs[rx->dcb_index].db[rx->db_index];
 	page = rx->page[rx->dcb_index][rx->db_index];
 	skb = build_skb(page_address(page), PAGE_SIZE << rx->page_order);
 	if (unlikely(!skb))
 		goto unmap_page;

 	dma_unmap_single(lan966x->dev, (dma_addr_t)db->dataptr,
 			 FDMA_DCB_STATUS_BLOCKL(db->status),
 			 DMA_FROM_DEVICE);
 	skb_put(skb, FDMA_DCB_STATUS_BLOCKL(db->status));

 	lan966x_ifh_get_src_port(skb->data, &src_port);
 	lan966x_ifh_get_timestamp(skb->data, &timestamp);

-	WARN_ON(src_port >= lan966x->num_phys_ports);
+	if (WARN_ON(src_port >= lan966x->num_phys_ports))
+		goto free_skb;

 	skb->dev = lan966x->ports[src_port]->dev;
 	skb_pull(skb, IFH_LEN * sizeof(u32));

 	if (likely(!(skb->dev->features & NETIF_F_RXFCS)))
 		skb_trim(skb, skb->len - ETH_FCS_LEN);

 	lan966x_ptp_rxtstamp(lan966x, skb, timestamp);
 	skb->protocol = eth_type_trans(skb, skb->dev);

 	if (lan966x->bridge_mask & BIT(src_port)) {
 		skb->offload_fwd_mark = 1;

 		skb_reset_network_header(skb);
 		if (!lan966x_hw_offload(lan966x, src_port, skb))
 			skb->offload_fwd_mark = 0;
 	}

 	skb->dev->stats.rx_bytes += skb->len;
 	skb->dev->stats.rx_packets++;

 	return skb;

+free_skb:
+	kfree_skb(skb);
 unmap_page:
 	dma_unmap_page(lan966x->dev, (dma_addr_t)db->dataptr,
 		       FDMA_DCB_STATUS_BLOCKL(db->status),
 		       DMA_FROM_DEVICE);
 	__free_pages(page, rx->page_order);

 	return NULL;
 }



